// bigfile.mjs — the /bigfile/ page: generate a 2–4 GiB PDF in the browser and
// open it ranged. Asserts the page itself, not just the engine, because this is
// the artefact a human clicks.
//
//   node test/bigfile.mjs
//
// The fixture is generated by examples/server.mjs (`/bigfile/generate`), so no
// 4 GiB file and no sparse file exist anywhere: the file is three virtual
// segments streamed on demand.

import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { createServer } from 'node:net';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { launchChrome, newPage } from './cdp.mjs';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const GIB = 1073741824;
const verbose = process.argv.includes('--verbose');

let passed = 0;
const failures = [];
async function step(name, fn) {
  try {
    await fn();
    passed++;
    console.log(`  ok  ${name}`);
  } catch (err) {
    failures.push({ name, err });
    console.error(`  FAIL ${name}\n       ${err.message.split('\n').join('\n       ')}`);
  }
}

const freePort = () => new Promise((resolve) => {
  const probe = createServer();
  probe.listen(0, '127.0.0.1', () => {
    const { port } = probe.address();
    probe.close(() => resolve(port));
  });
});

const chrome = await launchChrome({ port: 9343, url: 'about:blank' });
const servers = [];

async function startServer() {
  const port = await freePort();
  const proc = spawn(process.execPath, [join(root, 'examples', 'server.mjs'), String(port)], {
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  servers.push(proc);
  let log = '';
  proc.stdout.on('data', (d) => { log += String(d); });
  proc.stderr.on('data', (d) => { log += String(d); });
  await new Promise((resolve, reject) => {
    const t = setTimeout(() => reject(new Error(`server did not start\n${log}`)), 10000);
    const poll = setInterval(() => {
      if (log.includes('demos on')) { clearTimeout(t); clearInterval(poll); resolve(); }
    }, 50);
  });
  return port;
}

/** Click a size button and wait until the page settles (stats filled or refused). */
async function openSize(page, gib, { timeout = 120000 } = {}) {
  await page.eval(`document.querySelector('[data-gib="${gib}"]').click(); true`);
  const started = Date.now();
  while (Date.now() - started < timeout) {
    const state = await page.eval(`(() => ({
      status: document.getElementById('status').textContent,
      openMs: document.getElementById('openMs').textContent,
      scene: !!document.querySelector('#view canvas'),
      note: document.getElementById('note').textContent,
      stat: (id) => document.getElementById(id).textContent,
      fetched: document.getElementById('fetched').textContent,
      pages: document.getElementById('pagesCount').textContent,
      ranged: document.getElementById('ranged').textContent,
      heap: document.getElementById('heap').textContent,
      requests: document.getElementById('requests').textContent,
      percent: document.getElementById('percent').textContent,
      window: document.getElementById('window').textContent,
    }))()`);
    if (state.openMs !== '—' || state.status === 'refused') return state;
    await new Promise((r) => setTimeout(r, 250));
  }
  throw new Error('page never settled');
}

const gibToBytes = (n) => Math.round(n * GIB);
const kb = (text) => {
  const m = /^([\d.]+)\s*(B|KB|MB|GiB)$/.exec(text.trim());
  if (!m) return NaN;
  const v = Number(m[1]);
  return v * { B: 1, KB: 1024, MB: 1048576, GiB: GIB }[m[2]];
};

try {
  const port = await startServer();
  const page = await newPage(9343, 'about:blank');
  await page.setViewport(1280, 1000, 1);
  await page.goto(`http://127.0.0.1:${port}/examples/bigfile/`);

  const three = await openSize(page, '3.99');
  if (verbose) console.log('       ', JSON.stringify(three));

  await step('3.99 GiB: the page generates and opens the file ranged', () => {
    assert.equal(three.ranged, 'true', `ranged=${three.ranged}, note=${three.note}`);
    assert.equal(three.pages, '12');
    assert.equal(three.scene, true, 'no canvas — nothing rendered');
  });

  await step('3.99 GiB: it reads well under 2 MB of the file', () => {
    const fetched = kb(three.fetched);
    assert.ok(fetched > 0, `fetched=${three.fetched}`);
    assert.ok(fetched < 2 * 1048576, `fetched ${three.fetched} of ${three.percent}`);
    console.log(`       ${three.fetched} fetched in ${three.requests} requests ` +
                `(${three.percent}), window ${three.window}, heap ${three.heap}, open ${three.openMs}`);
  });

  const four = await openSize(page, '4');
  await step('4 GiB exactly (2^32): still opens — the limit is above, not at', () => {
    assert.equal(four.ranged, 'true', `ranged=${four.ranged}, note=${four.note}`);
    assert.equal(four.scene, true);
    assert.ok(kb(four.fetched) < 2 * 1048576, `fetched ${four.fetched}`);
    console.log(`       ${four.fetched} fetched in ${four.requests} requests, heap ${four.heap}, open ${four.openMs}`);
  });

  const over = await openSize(page, '4.1');
  await step('4.1 GiB: refused by name, not as "empty document"', () => {
    assert.equal(over.status, 'refused', `status ${over.status}`);
    assert.match(over.note, /4 GiB/, `note: ${over.note}`);
    assert.doesNotMatch(over.note, /empty document/i, `note: ${over.note}`);
    console.log(`       ${over.note.split('\n')[0].slice(0, 120)}`);
  });

  // The generated file must be a real PDF, not a byte-count illusion: MuPDF is
  // the reference, and it can read the same URL.
  const head = await page.eval(`(async () => {
    const r = await fetch('/bigfile/generate?size=${gibToBytes(2)}&pages=3', { method: 'HEAD' });
    const r2 = await fetch('/bigfile/generate?size=${gibToBytes(2)}&pages=3', { headers: { Range: 'bytes=-400' } });
    const buf = new Uint8Array(await r2.arrayBuffer());
    return { len: r.headers.get('content-length'), ranges: r.headers.get('accept-ranges'),
             status: r2.status, tail: new TextDecoder().decode(buf) };
  })()`);
  await step('HEAD reports the size and ranges; the tail is a real xref/trailer', () => {
    assert.equal(head.len, String(gibToBytes(2)));
    assert.equal(head.ranges, 'bytes');
    assert.equal(head.status, 206);
    assert.match(head.tail, /startxref/);
    assert.match(head.tail, /%%EOF/);
  });

  await page.close();
} finally {
  chrome.kill();
  for (const s of servers) s.kill('SIGKILL');
}

console.log(`\n${passed} step${passed === 1 ? '' : 's'} passed${failures.length ? `, ${failures.length} failed` : ''}`);
process.exit(failures.length ? 1 : 0);
